let selectedStart = {TimeRange:start};
let selectedEnd = {TimeRange:end};
let windowUsage = materialize(
    Usage
| where TimeGenerated >= selectedStart - 1h and TimeGenerated < selectedEnd + 1h
| where StartTime < selectedEnd and EndTime > selectedStart and EndTime > StartTime
| project StartTime, EndTime, Quantity, IsBillable, DataType,
    ObservedPlan = trim(' ', tostring(column_ifexists('Plan', '')))
);
let firstObserved = toscalar(windowUsage | summarize min(StartTime));
let lastObserved = toscalar(windowUsage | summarize max(EndTime));
let observedStart = max_of(selectedStart, firstObserved);
let observedEnd = min_of(selectedEnd, lastObserved);
let observedDays = (observedEnd - observedStart) / 1d;
let observedDayCount = toscalar(windowUsage | summarize by day = startofday(max_of(StartTime, selectedStart)) | count);
let expectedDayCount = tolong((startofday(observedEnd - 1tick) - startofday(observedStart)) / 1d) + 1;
windowUsage
| extend CoveredQuantity = Quantity * ((min_of(EndTime, selectedEnd) - max_of(StartTime, selectedStart)) / (EndTime - StartTime))
| summarize AnalyticsRows = countif(IsBillable == true and ObservedPlan =~ 'Analytics'),
    OtherRows = countif(IsBillable == true and ObservedPlan !~ 'Analytics'),
    AnalyticsQuantity = sumif(CoveredQuantity, IsBillable == true and ObservedPlan =~ 'Analytics')
    by TableName = DataType
| extend AnalyticsDailyGB = iff(AnalyticsRows > 0 and observedDays > 0, AnalyticsQuantity / 1000.0 / observedDays, real(null)),
    UsageWindowDays = observedDays,
    UsageWindowStatus = case(observedDayCount < expectedDayCount, 'Gaps',
        observedStart > selectedStart or observedEnd < selectedEnd, 'Partial', 'Selected'),
    UsageObservedStart = format_datetime(observedStart, 'yyyy-MM-dd HH:mm'),
    UsageObservedEnd = format_datetime(observedEnd, 'yyyy-MM-dd HH:mm')
| extend AnalyticsRateSet = iff(todouble('{RetentionAnalyticsRate}') > 0, 'Yes', 'No'),
    LongTermRateSet = iff(todouble('{RetentionLongTermRate}') > 0, 'Yes', 'No'),
    ScenarioAnalyticsDays = toint('{RetentionScenarioAnalyticsDays}'),
    ScenarioValid = iff(toint('{RetentionScenarioTotalDays}') >= toint('{RetentionScenarioAnalyticsDays}'), 'Yes', 'No')
| project TableName, AnalyticsDailyGB, AnalyticsRows, OtherRows, AnalyticsRateSet, LongTermRateSet, ScenarioAnalyticsDays, ScenarioValid,
    UsageWindowDays, UsageWindowStatus, UsageObservedStart, UsageObservedEnd
